function createLoopControlTool({ getLoopController }) {
  return {
    name: "loop_control",
    label: "Loop Control",
    description: "Control this session's active recurring loop (started with /loop). Only usable while a loop is active; calls outside an active loop fail. action=schedule sets the single fallback alarm that wakes this session after delay_seconds \u2014 background work completion wakes the session automatically, so never schedule alarms to poll it; alarms are for external state the system cannot observe, and for long hang-protection fallbacks. A new schedule replaces the previous alarm. action=complete declares the loop task achieved and ends the loop.",
    parameters: Type.Object({
      action: StringEnum(["schedule", "complete"], {
        description: "schedule: set the fallback wakeup alarm. complete: end the loop because its goal is achieved."
      }),
      delay_seconds: Type.Optional(Type.Number({
        description: "schedule only, required: seconds until the wakeup fires. Clamped to the loop's minimum; long fallbacks (>= 20 min) required while background work is live."
      })),
      reason: Type.Optional(Type.String({
        description: "schedule: context shown back to you when the wakeup fires. complete: short completion summary."
      }))
    }),
    sessionPermission: {
      resolveInvocation: () => ({
        action: "control",
        kind: "routine",
        capability: "loop_control.control"
      })
    },
    execute: async (_toolCallId, params, _signal, _onUpdate, ctx) => {
      const controller = getLoopController();
      if (!controller) return text4(t("tool.loopControl.serviceUnavailable"));
      const sessionPath = getToolSessionPath(ctx);
      if (!sessionPath) return text4(t("tool.loopControl.noActiveSession"));
      const loop = controller.toolStatus(sessionPath);
      if (!loop || loop.status !== "running" && loop.status !== "paused") {
        return text4(t("tool.loopControl.noActiveLoop"));
      }
      try {
        if (params.action === "schedule") {
          if (typeof params.delay_seconds !== "number") {
            return text4(t("tool.loopControl.delayRequired"));
          }
          const r = controller.toolSchedule(sessionPath, params.delay_seconds, params.reason || "");
          return text4(t("tool.loopControl.scheduled", {
            seconds: r.effectiveDelaySec,
            wakeAt: new Date(r.wakeAt).toISOString()
          }));
        }
        await controller.toolComplete(sessionPath, params.reason || "");
        return text4(t("tool.loopControl.completed"));
      } catch (err) {
        return text4(err?.message || String(err));
      }
    }
  };
}

