function createUsageRoute(engine) {
  const route = new Hono32();
  route.get("/usage/llm", (c2) => {
    const query = c2.req.query();
    const filter = {};
    for (const key of [
      "since",
      "until",
      "attributionKind",
      "sessionId",
      "sessionPath",
      "childSessionId",
      "childSessionPath",
      "agentId",
      "subsystem",
      "operation",
      "modelId",
      "provider",
      "status"
    ]) {
      if (typeof query[key] === "string" && query[key].trim()) filter[key] = query[key].trim();
    }
    const hasDateWindow = !!filter.since || !!filter.until;
    if (typeof query.limit === "string" && query.limit.trim()) {
      const rawLimit = query.limit.trim().toLowerCase();
      if (rawLimit !== "all") {
        const limit = Number(rawLimit);
        filter.limit = Number.isFinite(limit) && limit > 0 ? Math.min(Math.floor(limit), 2e3) : 500;
      }
    } else if (!hasDateWindow) {
      filter.limit = 500;
    }
    return c2.json(engine.usageLedger.list(filter));
  });
  return route;
}

